/** Msg is the write side of the jewel register. */
export interface Msg {
  /**
   * UpdateParams sets the settings and appoints the office. Governance only;
   * the office must be a group account.
   */
  UpdateParams(request: MsgUpdateParams): Promise<MsgUpdateParamsResponse>;
  /** AdmitJeweler admits a business and opens its collection. Office only. */
  AdmitJeweler(request: MsgAdmitJeweler): Promise<MsgAdmitJewelerResponse>;
  /** SuspendJeweler stops a jeweler acting: no registration, no sale of its stock, and its staff's offers die. Office only. */
  SuspendJeweler(request: MsgSuspendJeweler): Promise<MsgSuspendJewelerResponse>;
  /** ReinstateJeweler lets a suspended jeweler act again. Office only. */
  ReinstateJeweler(request: MsgReinstateJeweler): Promise<MsgReinstateJewelerResponse>;
  /** SetStaff adds and removes the people who act for a jeweler. */
  SetStaff(request: MsgSetStaff): Promise<MsgSetStaffResponse>;
  /** RegisterJewel mints a jewel into its jeweler's stock. */
  RegisterJewel(request: MsgRegisterJewel): Promise<MsgRegisterJewelResponse>;
  /** AmendJewel appends a correction to a jewel's record. */
  AmendJewel(request: MsgAmendJewel): Promise<MsgAmendJewelResponse>;
  /** OfferJewel opens an offer to an account or a claim key. */
  OfferJewel(request: MsgOfferJewel): Promise<MsgOfferJewelResponse>;
  /** CancelOffer closes an open offer. */
  CancelOffer(request: MsgCancelOffer): Promise<MsgCancelOfferResponse>;
  /** AcceptOffer takes a jewel offered to the signer's account. */
  AcceptOffer(request: MsgAcceptOffer): Promise<MsgAcceptOfferResponse>;
  /** ClaimOffer takes a jewel offered to a claim key. */
  ClaimOffer(request: MsgClaimOffer): Promise<MsgClaimOfferResponse>;
  /** ReportStolen flags a jewel and closes its offer. */
  ReportStolen(request: MsgReportStolen): Promise<MsgReportStolenResponse>;
  /** ClearStolen lifts the flag. */
  ClearStolen(request: MsgClearStolen): Promise<MsgClearStolenResponse>;
  /** AttachBenefit adds a benefit to a jewel. */
  AttachBenefit(request: MsgAttachBenefit): Promise<MsgAttachBenefitResponse>;
  /** RedeemBenefit records one use, with the owner's signed voucher. */
  RedeemBenefit(request: MsgRedeemBenefit): Promise<MsgRedeemBenefitResponse>;
  /** ProposeReassignment opens the public window. Office only. */
  ProposeReassignment(request: MsgProposeReassignment): Promise<MsgProposeReassignmentResponse>;
  /** VetoReassignment closes it. The current owner only. */
  VetoReassignment(request: MsgVetoReassignment): Promise<MsgVetoReassignmentResponse>;
  /** CompleteReassignment moves the jewel once the window has passed. Anyone. */
  CompleteReassignment(request: MsgCompleteReassignment): Promise<MsgCompleteReassignmentResponse>;
}

